private.reference_solution:
if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var stepCount) || stepCount < 1 || stepCount > 5) Environment.Exit(1);
Transformer chain = null!;
for (var i = 0; i < stepCount; i++)
{
    var op = (Console.ReadLine() ?? "").Trim();
    Transformer? step = op switch
    {
        "square" => TransformOps.Square,
        "negate" => TransformOps.Negate,
        "increment" => TransformOps.Increment,
        _ => null,
    };
    if (step is null) Environment.Exit(1);
    chain += step;
}
if (!int.TryParse((Console.ReadLine() ?? "").Trim(), out var value)) Environment.Exit(1);
foreach (Transformer step in chain.GetInvocationList())
{
    value = step(value);
}
Console.WriteLine("result=" + value);

delegate int Transformer(int x);

static class TransformOps
{
    public static int Square(int x) => x * x;
    public static int Negate(int x) => -x;
    public static int Increment(int x) => x + 1;
}
